"""Update the content of //build/bazel/config/toolchain_tags/ for toolchain tags. See README.md for details."""

import argparse
import sys
import typing as T
from pathlib import Path

# Location of default output directory for generated files,
DEFAULT_OUTPUT_DIR = "build/bazel/config/toolchain_tags"

# The list of toolchain tags to expose to Bazel as individual bool_flag() targets.
# and their corresponding config_setting() targets.
DEFAULT_TAGS_LIST = (
    "asan",
    "cfi",
    "hwasan",
    "instrumented",
    "lsan",
    "lto",
    "tsan",
    "ubsan",
)


_COMMON_HEADER: str = """\
# Copyright 2026 The Fuchsia Authors. All rights reserved.
# Use of this source code is governed by a BSD-style license that can be
# found in the LICENSE file.

# AUTO-GENERATED BY //build/bazel/config/toolchain_tags/update.py
# DO NOT EDIT - See //build/bazel/config/toolchain_tags/README.md

"""

_APPLICABLE_LICENSES: str = """\
package(default_applicable_licenses = ["//:license"])
"""

_VARIABLES_BUILD_HEADER: str = (
    _COMMON_HEADER
    + """\
load("@bazel_skylib//rules:common_settings.bzl", "bool_flag")

"""
    + _APPLICABLE_LICENSES
)


def generate_build_bazel_content(tags: T.Sequence[str]) -> str:
    """Generate //build/bazel/config/toolchain_tags/BUILD.bazel

    Args:
        tags: A sequence of toolchain tag strings
    Returns:
        BUILD.bazel file content as a string.
    """
    content = _VARIABLES_BUILD_HEADER
    for tag in tags:
        content += """
bool_flag(
    name = "{tag}",
    build_setting_default = False,
    visibility = ["//visibility:public"],
)
""".format(
            tag=tag
        )

    return content


_SELECT_BUILD_HEADER = _COMMON_HEADER + _APPLICABLE_LICENSES


def generate_select_build_bazel_content(tag: str) -> str:
    content = _SELECT_BUILD_HEADER
    content += r"""
config_setting(
    name = "true",
    flag_values = {
        "//build/bazel/config/toolchain_tags:{tag}": "True",
    },
    visibility = ["//visibility:public"],
)

config_setting(
    name = "false",
    flag_values = {
        "//build/bazel/config/toolchain_tags:{tag}": "False",
    },
    visibility = ["//visibility:public"],
)

alias(
    name = "{tag}",
    actual = ":true",
    visibility = ["//visibility:public"],
)
""".replace(
        "{tag}", tag
    )
    return content


def generate_toolchain_tags_gni(tags: T.Sequence[str]) -> str:
    content = _COMMON_HEADER
    content += """\
# This file is included from //build/bazel/config/bazel_args.gni
# (evaluated in the context of fuchsia_default_variant_toolchain and
# host_default_variant_toolchain) to define toolchain_tags_bazel_args,
# a list of Bazel configuration flags reflecting the values of
# toolchain_variant.tags for the current variant toolchain.

toolchain_tags_bazel_args = []

_variant_tags = toolchain_variant.tags

_toolchain_tags = [
{{toolchain_tags}}
]

foreach(tag, _toolchain_tags) {
  if (_variant_tags + [ tag ] - [ tag ] != _variant_tags) {
    toolchain_tags_bazel_args +=
        [ "--//build/bazel/config/toolchain_tags:$tag=True" ]
  } else {
    toolchain_tags_bazel_args +=
        [ "--//build/bazel/config/toolchain_tags:$tag=False" ]
  }
}
""".replace(
        "{{toolchain_tags}}", "\n".join('  "{}",'.format(tag) for tag in tags)
    )

    return content


def generate_content_dict(tags: T.Sequence[str]) -> dict[str, str]:
    result = {
        "BUILD.bazel": generate_build_bazel_content(tags),
        "toolchain_tags.gni": generate_toolchain_tags_gni(tags),
    }
    for tag in tags:
        result[f"{tag}/BUILD.bazel"] = generate_select_build_bazel_content(tag)

    return result


def write_if_changed(path: Path, content: str) -> None:
    if path.exists():
        current_content = path.read_text()
        if current_content == content:
            return
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.is_symlink():
        path.unlink()
    path.write_text(content)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--fuchsia-dir", type=Path, help="Path to Fuchsia source directory"
    )
    parser.add_argument(
        "--config-output-dir",
        type=Path,
        help=f"Path to output directory, default $FUCHSIA_DIR/{DEFAULT_OUTPUT_DIR}",
    )
    parser.add_argument(
        "--tags-list",
        action="append",
        help=f"Comma-separated list of tags, default is {DEFAULT_TAGS_LIST}",
    )
    parser.add_argument(
        "--tags-list-file",
        type=Path,
        help="Path to input tags list file (one tag per line)",
    )
    args = parser.parse_args()

    if args.fuchsia_dir:
        fuchsia_dir = args.fuchsia_dir
    else:
        # Assume this is under //build/bazel/config/toolchain_tags/
        fuchsia_dir = Path(__file__).parent.parent.parent.parent.parent

    fuchsia_dir = fuchsia_dir.resolve()
    if not (fuchsia_dir / ".jiri_manifest").exists():
        parser.error(f"Not a Fuchsia source directory: {fuchsia_dir}")

    if args.config_output_dir:
        output_dir = args.config_output_dir.resolve()
    else:
        output_dir = fuchsia_dir / DEFAULT_OUTPUT_DIR

    tags_list: T.Sequence[str]
    if args.tags_list is not None:
        if args.tags_list_file:
            parser.error("Cannot use both --tags-list and --tags-list-file")
        tags_list = sorted(
            {
                tag.strip()
                for item in args.tags_list
                for tag in item.split(",")
                if tag.strip()
            }
        )
    elif args.tags_list_file:
        tags_list_lines = [
            line.strip()
            for line in args.tags_list_file.read_text().splitlines()
        ]
        tags_list = sorted(
            {
                line
                for line in tags_list_lines
                if line and not line.startswith("#")
            }
        )
    else:
        tags_list = DEFAULT_TAGS_LIST

    if not tags_list:
        parser.error("Cannot process empty tags list")

    content_dict = generate_content_dict(tags_list)
    for filepath, content in content_dict.items():
        write_if_changed(output_dir / filepath, content)

    # Remove stale auto-generated <tag>/BUILD.bazel files from omitted tags.
    active_tags = set(tags_list)
    for entry in output_dir.iterdir():
        if entry.is_dir() and entry.name not in active_tags:
            build_file = entry / "BUILD.bazel"
            if build_file.is_file() and build_file.read_text().startswith(
                _COMMON_HEADER
            ):
                build_file.unlink()
                if not any(entry.iterdir()):
                    entry.rmdir()

    return 0


if __name__ == "__main__":
    sys.exit(main())
